const body = $json.body?.message?.toolCalls?.[0]?.function?.arguments;

if (!body || typeof body !== 'object') {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'INVALID_TOOL_PAYLOAD',
          message: 'Could not find patient data in Vapi tool call'
        }
      }
    }
  ];
}

// Required fields
const requiredFields = [
  'first_name',
  'last_name',
  'date_of_birth',
  'sex',
  'phone_number',
  'address_line_1',
  'city',
  'state',
  'zip_code'
];

// Check required fields
const missingFields = requiredFields.filter(field => {
  return (
    body[field] === undefined ||
    body[field] === null ||
    String(body[field]).trim() === ''
  );
});

if (missingFields.length > 0) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: `Missing required fields: ${missingFields.join(', ')}`
        }
      }
    }
  ];
}

// Clean strings
const clean = value => {
  if (value === undefined || value === null || value === '') {
    return null;
  }

  return String(value).trim();
};

const patient = {
  first_name: clean(body.first_name),
  last_name: clean(body.last_name),
  date_of_birth: clean(body.date_of_birth),
  sex: clean(body.sex),
  phone_number: clean(body.phone_number),
  email: clean(body.email),
  address_line_1: clean(body.address_line_1),
  address_line_2: clean(body.address_line_2),
  city: clean(body.city),
  state: clean(body.state)?.toUpperCase(),
  zip_code: clean(body.zip_code),
  insurance_provider: clean(body.insurance_provider),
  insurance_member_id: clean(body.insurance_member_id),
  preferred_language: clean(body.preferred_language) || 'English',
  emergency_contact_name: clean(body.emergency_contact_name),
  emergency_contact_phone: clean(body.emergency_contact_phone)
};

// -------------------------
// Name validation
// -------------------------

const nameRegex = /^[A-Za-zÀ-ÿ' -]+$/;

for (const field of ['first_name', 'last_name']) {
  if (
    !nameRegex.test(patient[field]) ||
    patient[field].length < 1 ||
    patient[field].length > 50
  ) {
    return [
      {
        json: {
          valid: false,
          statusCode: 400,
          error: {
            code: 'VALIDATION_ERROR',
            message: `Invalid ${field}`
          }
        }
      }
    ];
  }
}

// -------------------------
// Date of birth
// -------------------------

if (!/^\d{4}-\d{2}-\d{2}$/.test(patient.date_of_birth)) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'date_of_birth must be YYYY-MM-DD'
        }
      }
    }
  ];
}

const dob = new Date(`${patient.date_of_birth}T00:00:00Z`);

if (Number.isNaN(dob.getTime())) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Invalid date_of_birth'
        }
      }
    }
  ];
}

const today = new Date();
today.setUTCHours(0, 0, 0, 0);

if (dob > today) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'date_of_birth cannot be in the future'
        }
      }
    }
  ];
}

// -------------------------
// Sex
// -------------------------

const validSexes = [
  'Male',
  'Female',
  'Other',
  'Decline to Answer'
];

if (!validSexes.includes(patient.sex)) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Invalid sex'
        }
      }
    }
  ];
}

// -------------------------
// Phone
// -------------------------

patient.phone_number = patient.phone_number.replace(/\D/g, '');

if (!/^\d{10}$/.test(patient.phone_number)) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'phone_number must contain exactly 10 digits'
        }
      }
    }
  ];
}

// -------------------------
// Email
// -------------------------

if (
  patient.email &&
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(patient.email)
) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Invalid email'
        }
      }
    }
  ];
}

// -------------------------
// State
// -------------------------

if (!/^[A-Z]{2}$/.test(patient.state)) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'state must be a 2-letter US state abbreviation'
        }
      }
    }
  ];
}

// -------------------------
// ZIP
// -------------------------

if (!/^\d{5}(-\d{4})?$/.test(patient.zip_code)) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Invalid ZIP code'
        }
      }
    }
  ];
}

// -------------------------
// Emergency phone
// -------------------------

if (patient.emergency_contact_phone) {
  patient.emergency_contact_phone =
    patient.emergency_contact_phone.replace(/\D/g, '');

  if (!/^\d{10}$/.test(patient.emergency_contact_phone)) {
    return [
      {
        json: {
          valid: false,
          statusCode: 400,
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Invalid emergency_contact_phone'
          }
        }
      }
    ];
  }
}

// -------------------------
// SUCCESS
// -------------------------

return [
  {
    json: {
      valid: true,
      statusCode: 200,
      patient
    }
  }
];

const patient = $('Validate Patient').first().json.patient;

// Normalize any phone value to its last 10 digits for a reliable comparison.
// The DB may store the number in a different format (spaces, dashes,
// leading country code, parentheses) than the validated 10-digit value.
const normalizePhone = (value) => {
  if (value === undefined || value === null) return '';
  const digits = String(value).replace(/\D/g, '');
  return digits.slice(-10);
};

const targetPhone = normalizePhone(patient.phone_number);

const existing = $input.all();

// A row is only a duplicate when it is a real patient row (has patient_id)
// AND its normalized phone number actually matches the incoming one.
// This guards against empty-json items (from alwaysOutputData) and against
// rows whose stored phone differs from what was validated.
const existingPatient = existing.find(
  (item) =>
    item.json &&
    item.json.patient_id &&
    targetPhone !== '' &&
    normalizePhone(item.json.phone_number) === targetPhone
);

if (existingPatient) {
  return [{
    json: {
      duplicate: true,
      existing_patient: existingPatient.json
    }
  }];
}

return [{
  json: {
    duplicate: false,
    patient
  }
}];

return [{
  json: {
    data: null,
    error: {
      code: 'DUPLICATE_PATIENT',
      message: 'A patient with this phone number already exists.',
      patient_id: $json.existing_patient.patient_id
    }
  }
}];

const patient = $input.first().json;

console.log('PATIENT_CREATED', JSON.stringify(patient));

return [{
  json: {
    data: patient,
    error: null
  }
}];
